<?php
/** Proof — JSON mode (spec "Proof", 8): every handler under a signed action token answers {ok, did, location}; 422 {error:{code invalid, fields}}; _partial=1; a run token's rows are source agent and the rights hold. */
require __DIR__ . '/lib.php';
$fx = ar_fixture();
$bea = ['X-Action-Token: ' . person_token(27)]; $owner = ['X-Action-Token: ' . person_token(1)];
$wrong = []; $count = 0;
$call = function (string $label, string $path, array $form, array $h, bool $location = true) use (&$wrong, &$count): array {
    [$c, $b] = act_token($path, $form, $h);
    $count++;
    if ($c !== 200 || !($b['ok'] ?? false) || !isset($b['did']) || ($location && !isset($b['location']))) { $wrong[] = "$label $c " . msg($b); }
    return $b;
};
echo "1. Customers and contacts\n";
$b = $call('customer_save', '/customers/save.php', ['name' => 'SMOKE Json Customer', 'email' => 'json@example.invalid', 'terms_days' => '10'], $bea);
$cust = (int) $b['record_id'];
ok(preg_match('#^/customers/' . $cust . '\?notice=saved$#', $b['location']) === 1, 'customer_save: record_id and a location ending in it');
$call('customer_save (update)', '/customers/save.php', ['customer' => $cust, 'phone' => '555'], $bea);
$b = $call('contact_save', '/customers/contact.php', ['party_kind' => 'customer', 'party' => $cust, 'name' => 'SMOKE Jo', 'email' => 'jo@example.invalid', 'is_primary' => 'yes'], $bea);
$call('contact_remove', '/customers/contact-remove.php', ['contact' => $b['record_id']], $bea);
echo "2. Invoices\n";
$lines = json_encode([['description' => 'Json line', 'quantity' => '2', 'unit_price' => '50.00', 'income_account' => '4100', 'tax_rate' => (string) $fx['tax']]]);
$b = $call('invoice_draft', '/invoices/save.php', ['customer' => $cust, 'issue_date' => '2026-06-01', 'memo' => 'SMOKE json', 'lines' => $lines], $bea);
$inv = (int) $b['record_id'];
ok(preg_match('#^/invoices/' . $inv . '\?notice=saved$#', $b['location']) === 1, 'invoice_draft: record_id and the location');
$call('invoice_update', '/invoices/save.php', ['invoice' => $inv, 'memo' => 'SMOKE json changed'], $bea);
$b = $call('invoice_line_save', '/invoices/line-save.php', ['invoice' => $inv, 'description' => 'Second', 'quantity' => '1', 'unit_price' => '10', 'income_account' => '4100'], $bea);
ok(isset($b['totals']['total']) && $b['totals']['total'] === '118.25', 'a line write answers the totals (118.25)');
$call('invoice_line_save (change)', '/invoices/line-save.php', ['invoice' => $inv, 'line' => $b['record_id'], 'quantity' => '2'], $bea);
$call('invoice_line_remove', '/invoices/line-remove.php', ['invoice' => $inv, 'line' => $b['record_id']], $bea);
$b = $call('invoice_issue', '/invoices/issue.php', ['invoice' => $inv], $bea);
ok(preg_match('/^INV-\d{5}$/', (string) ($b['number'] ?? '')) === 1 && ($b['amount'] ?? '') === '108.25', 'invoice_issue answers the number and the amount (108.25)');
$call('invoice_send', '/invoices/send.php', ['invoice' => $inv, 'to_email' => 'json@example.invalid'], $bea);
$call('secure_link_rotate', '/invoices/secure-link.php', ['invoice' => $inv], $bea);
$late = (int) $call('invoice_draft (late)', '/invoices/save.php', ['customer' => $cust, 'issue_date' => '2026-06-01', 'due_date' => '2026-06-15', 'lines' => $lines], $bea)['record_id'];
act_token('/invoices/issue.php', ['invoice' => $late], $bea);
$b = $call('invoice_remind', '/invoices/remind.php', ['invoice' => $late], $bea);
ok(($b['step'] ?? 0) === 3, 'invoice_remind answers the step (3: months overdue)');
$v = (int) act_token('/invoices/save.php', ['customer' => $cust, 'issue_date' => '2026-06-02', 'lines' => $lines], $bea)[1]['record_id'];
act_token('/invoices/issue.php', ['invoice' => $v], $bea);
$call('invoice_void', '/invoices/void.php', ['invoice' => $v, 'reason' => 'SMOKE json void'], $owner);
$wo = (int) act_token('/invoices/save.php', ['customer' => $cust, 'issue_date' => '2026-06-03', 'lines' => $lines], $bea)[1]['record_id'];
act_token('/invoices/issue.php', ['invoice' => $wo], $bea);
$call('invoice_write_off', '/invoices/write-off.php', ['invoice' => $wo, 'reason' => 'SMOKE json write-off'], $owner);
$dd = (int) act_token('/invoices/save.php', ['customer' => $cust, 'lines' => $lines], $bea)[1]['record_id'];
$call('invoice_delete', '/invoices/delete.php', ['invoice' => $dd], $bea);
echo "3. Receipts, claims and deposits\n";
$b = $call('receipt_record', '/receipts/save.php', ['customer' => $cust, 'amount' => '60', 'method' => 'transfer', 'invoice' => $inv], $bea);
$r1 = (int) $b['record_id'];
ok(preg_match('#^/receipts/' . $r1 . '\?notice=recorded$#', $b['location']) === 1 && ($b['applied'][0]['amount'] ?? '') === '60.00', 'receipt_record: record_id, location, applied[]');
$b = $call('receipt_record (unapplied)', '/receipts/save.php', ['customer' => $cust, 'amount' => '20', 'method' => 'cash'], $bea);
$r2 = (int) $b['record_id'];
$call('receipt_apply', '/receipts/apply.php', ['receipt' => $r2, 'invoice' => $inv, 'amount' => '20'], $bea);
$call('receipt_unapply', '/receipts/unapply.php', ['receipt' => $r2, 'invoice' => $inv], $bea);
$call('receipt_void', '/receipts/void.php', ['receipt' => $r2, 'reason' => 'SMOKE json'], $owner);
q("INSERT INTO receipt_claims (invoice_id, claimed_on, method, amount, ip_address) VALUES (:i, '2026-06-10', 'cash', 10, '127.0.0.1'), (:i, '2026-06-11', 'cash', 5, '127.0.0.1')", ['i' => $inv]);
[$k1, $k2] = array_map('intval', array_column(q('SELECT id FROM receipt_claims WHERE invoice_id = :i ORDER BY id DESC LIMIT 2', ['i' => $inv]), 'id'));
$call('claim_confirm', '/receipts/claim-confirm.php', ['claim' => $k1], $bea);
$call('claim_dismiss', '/receipts/claim-dismiss.php', ['claim' => $k2, 'reason' => 'SMOKE'], $bea);
$r3 = (int) act_token('/receipts/save.php', ['customer' => $cust, 'amount' => '33', 'method' => 'cheque'], $bea)[1]['record_id'];
$r4 = (int) act_token('/receipts/save.php', ['customer' => $cust, 'amount' => '44', 'method' => 'cheque'], $bea)[1]['record_id'];
$b = $call('deposit_draft', '/deposits/save.php', ['bank_account' => $fx['bank'], 'receipts' => [$r3]], $bea);
$dep = (int) $b['record_id'];
$call('deposit_add_receipt', '/deposits/add.php', ['deposit' => $dep, 'receipt' => $r4], $bea);
$call('deposit_remove_receipt', '/deposits/remove.php', ['deposit' => $dep, 'receipt' => $r4], $bea);
$call('deposit_record', '/deposits/record.php', ['deposit' => $dep], $bea);
$call('deposit_void', '/deposits/void.php', ['deposit' => $dep, 'reason' => 'SMOKE json'], $owner);
$dep2 = (int) act_token('/deposits/save.php', ['bank_account' => $fx['bank'], 'receipts' => [$r3]], $bea)[1]['record_id'];
$call('deposit_delete', '/deposits/delete.php', ['deposit' => $dep2], $bea);
echo "4. Credit notes and the statement\n";
$b = $call('credit_note_draft', '/credit-notes/save.php', ['customer' => $cust, 'invoice' => $inv, 'lines' => json_encode([['description' => 'Json credit', 'quantity' => '1', 'unit_price' => '20.00', 'income_account' => '4100']])], $bea);
$cn = (int) $b['record_id'];
$call('credit_note_update', '/credit-notes/save.php', ['credit_note' => $cn, 'reason' => 'SMOKE json'], $bea);
$b = $call('credit_note_line_save', '/credit-notes/line-save.php', ['credit_note' => $cn, 'description' => 'More', 'quantity' => '1', 'unit_price' => '5', 'income_account' => '4100'], $bea);
$call('credit_note_line_remove', '/credit-notes/line-remove.php', ['credit_note' => $cn, 'line' => $b['record_id']], $bea);
$call('credit_note_issue', '/credit-notes/issue.php', ['credit_note' => $cn], $bea);
$call('credit_note_apply', '/credit-notes/apply.php', ['credit_note' => $cn, 'invoice' => $inv, 'amount' => '10'], $bea);
$call('credit_note_unapply', '/credit-notes/unapply.php', ['credit_note' => $cn, 'invoice' => $inv], $bea);
$call('credit_note_void', '/credit-notes/void.php', ['credit_note' => $cn, 'reason' => 'SMOKE json'], $owner);
$cn2 = (int) act_token('/credit-notes/save.php', ['customer' => $cust, 'lines' => json_encode([['description' => 'Delete me', 'quantity' => '1', 'unit_price' => '1', 'income_account' => '4100']])], $bea)[1]['record_id'];
$call('credit_note_delete', '/credit-notes/delete.php', ['credit_note' => $cn2], $bea);
$call('statement_send', '/customers/statement-send.php', ['customer' => $cust, 'from' => '2026-01-01', 'to' => '2026-12-31'], $bea);
$archived = (int) act_token('/customers/save.php', ['name' => 'SMOKE Json Archive'], $bea)[1]['record_id'];
$call('customer_archive', '/customers/archive.php', ['customer' => $archived], $bea);
$call('customer_delete', '/customers/delete.php', ['customer' => $archived], $owner);
ok($wrong === [], "$count handlers answer {ok, did, location}" . ($wrong ? ' — wrong: ' . implode('; ', $wrong) : ''));
echo "5. Refusals\n";
[$c, $b] = act_token('/invoices/save.php', ['customer' => '', 'issue_date' => 'x', 'due_date' => 'y'], $bea);
$f = fields($b);
ok($c === 422 && ($b['error']['code'] ?? '') === 'invalid' && isset($f['customer'], $f['issue_date'], $f['due_date']) && count($b['error']['errors']) === 3, 'a bad invoice form: 422 {error: {code invalid, errors[3], fields{customer, issue_date, due_date}}}');
[$c, $b] = act_token('/invoices/save.php', ['customer' => $cust, 'lines' => json_encode([['description' => 'x', 'quantity' => '0', 'unit_price' => '1', 'income_account' => '4100'], ['description' => 'y', 'quantity' => '1', 'unit_price' => '1', 'income_account' => '9999']])], $bea);
ok($c === 422 && str_contains(msg($b), 'Row 1: the quantity is a number above zero') && (fields($b)['row'] ?? 0) === 1, 'a bad line row: 422 naming the row');
[$c, $b] = act_token('/invoices/save.php', ['customer' => $cust, 'lines' => json_encode([['description' => 'y', 'quantity' => '1', 'unit_price' => '1', 'income_account' => '9999']])], $bea);
ok($c === 422 && str_contains(msg($b), 'Row 1:'), 'an unknown account code: 422 naming the row (' . msg($b) . ')');
[$c, $b] = act_token('/invoices/issue.php', ['invoice' => 424242], $bea);
ok($c === 404 && msg($b) === 'Invoice not found.', 'an unknown invoice: 404 in one sentence');
[$c, $b] = act_token('/invoices/void.php', ['invoice' => $inv, 'reason' => 'x'], $bea);
ok($c === 403 && msg($b) === 'You may not reverse, void or write off.', 'the rights hold under a token: the Bookkeeper voiding → 403');
[$c, $b] = act_token('/invoices/issue.php', ['invoice' => $inv], ['X-Action-Token: ' . person_token(26)]);
ok($c === 403 && msg($b) === 'You may not keep the receivables.', 'a Viewer issuing → 403');
[$c, $b] = act_token('/invoices/issue.php', ['invoice' => $inv], ['X-Action-Token: ' . person_token(1, -5)]);
ok($c === 401, 'an expired token: 401');
echo "6. _partial=1 keeps the rest\n";
$p = (int) act_token('/invoices/save.php', ['customer' => $cust, 'issue_date' => '2026-07-01', 'due_date' => '2026-07-20', 'reference' => 'KEEP-ME', 'memo' => 'first', 'lines' => $lines], $bea)[1]['record_id'];
[$c, $b] = act_token('/invoices/save.php', ['invoice' => $p, 'memo' => 'changed', '_partial' => '1'], $bea);
$row = inv_row($p);
ok($c === 200 && $row['memo'] === 'changed' && $row['reference'] === 'KEEP-ME' && $row['due_date'] === '2026-07-20' && (int) $row['customer_id'] === $cust, 'invoice_update with _partial=1: the base row fills the rest');
$cnp = (int) act_token('/credit-notes/save.php', ['customer' => $cust, 'reason' => 'keep this', 'lines' => '[]'], $bea)[1]['record_id'];
[$c, $b] = act_token('/credit-notes/save.php', ['credit_note' => $cnp, 'issue_date' => '2026-08-01', '_partial' => '1'], $bea);
ok($c === 200 && (string) one('SELECT reason FROM credit_notes WHERE id = :c', ['c' => $cnp]) === 'keep this', 'credit_note_update with _partial=1 too');
[$c, $b] = act_token('/customers/save.php', ['customer' => $cust, 'notes' => 'partial note', '_partial' => '1'], $bea);
ok($c === 200 && (string) one('SELECT name FROM customers WHERE id = :c', ['c' => $cust]) === 'SMOKE Json Customer' && (string) one('SELECT terms_days FROM customers WHERE id = :c', ['c' => $cust]) === '10', 'customer_save with _partial=1 keeps the rest');
echo "7. An agent's run token\n";
kernel_state(function ($st) { $st['facts']['72'] = ['valid' => true, 'is_agent' => true, 'member_id' => 40, 'run_id' => 72, 'request_id' => 'req-run-72', 'trigger' => 'duty', 'is_eval' => false, 'endpoints' => [['name' => 'Records MCP']]]; return $st; });
[$tok, $relay] = run_token(40, 72);
$h = ['X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay];
$since = last_activity_id();
[$c, $b] = act_token('/invoices/save.php', ['customer' => $cust, 'lines' => $lines], $h);
$agentInv = (int) ($b['record_id'] ?? 0);
[$c2, $b2] = act_token('/invoices/issue.php', ['invoice' => $agentInv], $h);
ok($c === 200 && $c2 === 200, 'the Bookkeeper agent drafts and issues (ar.write; the pause on issue is the kernel\'s, proven in Phase 4)');
$rows = q("SELECT source, agent_run_id, request_id FROM activity_log WHERE id > :s AND action IN ('invoice.draft', 'invoice.issue') ORDER BY id", ['s' => $since]);
ok(count($rows) === 2 && $rows[0]['source'] === 'agent' && (int) $rows[0]['agent_run_id'] === 72 && $rows[0]['request_id'] === 'req-run-72' && $rows[1]['source'] === 'agent', 'its rows are source agent, run 72, the run\'s request id');
[$c, $b] = act_token('/invoices/void.php', ['invoice' => $agentInv, 'reason' => 'x'], $h);
ok($c === 403, 'the agent may not void (journal.override): 403');
[$c, $b] = act_token('/customers/delete.php', ['customer' => $cust], $h);
ok($c === 403, 'nor delete a customer: 403');
[$c, $b] = act_token('/invoices/save.php', ['customer' => $cust, 'lines' => '[]'], ['X-Action-Token: ' . $tok]);
ok($c === 401, 'the relay missing: 401');
kernel_state(function ($st) { unset($st['facts']); return $st; });
echo "8. The screens answer JSON\n";
$hj = array_merge(JSONH, $bea);
$r = req('GET', '/invoices/' . $inv, ['headers' => $hj]); $d = json_decode($r['body'], true)['data'] ?? [];
ok($r['code'] === 200 && $d['invoice']['invoice_id'] === $inv && isset($d['invoice']['lines'], $d['invoice']['receipts'], $d['invoice']['credits'], $d['invoice']['claims'], $d['attachments'], $d['timeline'], $d['may']) && !str_contains($r['body'], 'held for invoice_send'), 'the invoice: head, lines, receipts, credits, claims, attachments, timeline');
$hold = held_token($inv);
ok($hold !== null && !str_contains($r['body'], $hold), 'and never the token');
foreach (['/customers/', '/customers/' . $cust, '/invoices/', '/credit-notes/', '/credit-notes/' . $cn, '/receipts/', '/receipts/' . $r1, '/receipts/claims', '/deposits/', '/deposits/' . $dep, '/customers/' . $cust . '/statement', '/receipts/new?customer=' . $cust, '/deposits/new', '/invoices/new', '/credit-notes/new', '/customers/new'] as $path) {
    $r = req('GET', $path, ['headers' => $hj]);
    if ($r['code'] !== 200 || !isset(json_decode($r['body'], true)['data'])) { $bad[] = "$path {$r['code']}"; }
}
ok(empty($bad), 'sixteen screens answer JSON' . (empty($bad) ? '' : ' — wrong: ' . implode('; ', $bad)));
finish();
